module top_pad(clk, rst, sclk, cs_n, mosi, miso);
  input clk, rst, sclk, cs_n, mosi;
  output miso;
  wire clk, rst, sclk, cs_n, mosi;
  wire miso;
  wire clk_PAD, cs_n_PAD, miso_PAD, mosi_PAD, rst_PAD, sclk_PAD;

pad_corner corner0 ();
pad_corner corner1 ();
pad_corner corner2 ();
pad_corner corner3 ();
pad_vdd vdd0 ();
pad_gnd vss0 ();

  pad_in clk_pad(.pad (clk), .DataIn (clk_PAD));
  TopModule core(.clk (clk_PAD), .rst (rst_PAD), .sclk (sclk_PAD),
       .cs_n (cs_n_PAD), .mosi (mosi_PAD), .miso (miso_PAD));
  pad_in cs_n_pad(.pad (cs_n), .DataIn (cs_n_PAD));
  pad_out miso_pad(.pad (miso), .DataOut (miso_PAD));
  pad_in mosi_pad(.pad (mosi), .DataIn (mosi_PAD));
  pad_in rst_pad(.pad (rst), .DataIn (rst_PAD));
  pad_in sclk_pad(.pad (sclk), .DataIn (sclk_PAD));
endmodule

